 h5_header('面试评分');?><div class="interview-head"><div class="calendar"><b><?=e(date('d',strtotime($session['interview_date'])))?></b><small><?=e(strtoupper(date('M',strtotime($session['interview_date']))))?></small></div><div><small>今日面试场次</small><h1><?=e($session['post_name'])?></h1><p>◷ <?=e($session['time_range'])?>　⌖ <?=e($session['location'])?></p></div></div><?php
 if($step==='candidates'&&$auth):$st=$pdo->prepare('SELECT ic.id,c.name,r.total_score,(SELECT COUNT(*) FROM interview_score sc WHERE sc.interviewer_id=? AND sc.interview_candidate_id=ic.id) scored FROM interview_candidate ic JOIN candidate c ON c.id=ic.candidate_id JOIN answer a ON a.id=ic.answer_id JOIN result r ON r.answer_id=a.id WHERE ic.session_id=? ORDER BY ic.seq');$st->execute([$auth['si_id'],$session['id']]);$rows=$st->fetchAll();?><section class="h5-card candidates"><div class="signed">面试官：<b><?=e($auth['name'])?></b></div><h2>候选人列表</h2><?php foreach($rows as $r):?><a href="?m=interview&t=<?=e($t)?>&step=score&id=<?=$r['id']?>"><i><?=e(first_char($r['name']))?></i><span><b><?=e($r['name'])?></b><small>初试得分 <?=number_format($r['total_score'],1)?></small></span><em><?=$r['scored']?'已评分':'去评分 ›'?></em></a><?php endforeach;?></section><?php
 elseif($step==='score'&&$auth):$st=$pdo->prepare('SELECT ic.id,c.name FROM interview_candidate ic JOIN candidate c ON c.id=ic.candidate_id WHERE ic.id=? AND ic.session_id=?');$st->execute([(int)$_GET['id'],$session['id']]);$c=$st->fetch();if(!$c){?><div class="h5-empty"><b>候选人不存在</b></div><?php h5_footer();exit;}$st=$pdo->prepare('SELECT * FROM interview_score_draft WHERE interviewer_id=? AND interview_candidate_id=?');$st->execute([$auth['si_id'],$c['id']]);$draft=$st->fetch()?:[];$saved=json_decode($draft['detail_json']??'{}',true)?:[];$fixed=[['professional','专业知识与技能','30%'],['experience','工作经验与业绩','25%'],['communication','沟通表达能力','15%'],['logic','逻辑思维与分析','10%'],['teamwork','团队协作能力','10%'],['learning','学习与适应能力','5%'],['professionalism','仪表举止与职业素养','5%']];?><form class="h5-card h5-form fixed-score-form" method="post" action="?m=interview&t=<?=e($t)?>&step=score"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="candidate_id" value="<?=$c['id']?>"><h2>为 <?=e($c['name'])?> 评分</h2><p>每项按 1–5 分评价，系统按固定权重自动汇总</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><div class="score-guide"><span><b>5分 优秀</b>明显超出岗位要求</span><span><b>4分 良好</b>达到并略超岗位要求</span><span><b>3分 一般</b>基本达到岗位要求</span><span><b>2分 较差</b>部分达到，需要提升</span><span><b>1分 差</b>未达到基本要求</span></div><div class="fixed-dimensions"><?php foreach($fixed as [$code,$label,$weight]):?><fieldset><legend><b><?=e($label)?></b><small>权重 <?=$weight?></small></legend><div><?php for($n=1;$n<=5;$n++):?><label><input type="radio" name="dims[<?=$code?>]" value="<?=$n?>" <?=($saved[$code]??0)===$n?'checked':''?> required><span><?=$n?>分</span></label><?php endfor;?></div></fieldset><?php endforeach;?></div><h3 class="question-title">综合评价</h3><label>优势与亮点<textarea name="strengths" rows="3" required><?=e($draft['strengths']??'')?></textarea></label><label>不足与风险<textarea name="risks" rows="3" required><?=e($draft['risks']??'')?></textarea></label><label>发展建议<textarea name="development" rows="3"><?=e($draft['development']??'')?></textarea></label><label>录用建议<select name="recommendation" required><?php foreach(['strong'=>'强烈推荐录用','recommend'=>'推荐录用','pending'=>'待定 / 需要复试','reject'=>'不推荐录用'] as $v=>$label):?><option value="<?=$v?>" <?=($draft['recommendation']??'')===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label>建议薪资范围<input name="salary_range" value="<?=e($draft['salary_range']??'')?>" placeholder="例如：15K–18K"></label><label>预计到岗日期<input type="date" name="available_date" value="<?=e($draft['available_date']??'')?>"></label><div class="h5-actions"><button class="btn secondary" formaction="?m=interview&t=<?=e($t)?>&step=draft">保存草稿</button><button class="btn primary">确认提交评分</button></div></form><?php
 else:?><form class="h5-card verify interviewer" method="post" action="?m=interview&t=<?=e($t)?>&step=login"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="identity">◎</div><h2>确认面试官身份</h2><p>请输入您在本场面试名单中的姓名</p><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><label>本人姓名<input name="real_name" placeholder="请输入真实姓名" required></label><small class="safe">✓ 姓名将与本场预设面试官名单匹配</small><button class="btn primary">确认身份并进入评分</button><em>演示面试官姓名：李四 / 王五</em></form><?php endif;h5_footer();exit;
}

function load_questions(int $postId): array {
 $pdo=db();$set=$pdo->prepare("SELECT id FROM question_set WHERE post_id=? AND status='published' ORDER BY version DESC LIMIT 1");$set->execute([$postId]);$setId=(int)$set->fetchColumn();if(!$setId)return [];
 $base=$pdo->prepare("SELECT question_id id,NULL dim_code,q_type,stem_snapshot stem,options_snapshot options,answer_snapshot answer,score_snapshot score,'base' scope,sort FROM question_set_item WHERE question_set_id=? AND question_type='base' ORDER BY sort,id");$base->execute([$setId]);$post=$pdo->prepare("SELECT qsi.question_id id,NULL dim_code,COALESCE(qsi.q_type,q.q_type) q_type,COALESCE(qsi.stem_snapshot,q.stem) stem,COALESCE(qsi.options_snapshot,q.options) options,COALESCE(qsi.answer_snapshot,q.answer) answer,COALESCE(qsi.score_snapshot,q.score) score,'post' scope,qsi.sort FROM question_set_item qsi LEFT JOIN question_post q ON q.id=qsi.question_id WHERE qsi.question_set_id=? AND qsi.question_type='post' ORDER BY qsi.sort,id");$post->execute([$setId]);return [...$base->fetchAll(),...$post->fetchAll()];
}
function normalize_answer(mixed $value): string { if(is_array($value)){sort($value);return implode('|',$value);} $parts=array_filter(array_map('trim',preg_split('/[,，|]/',(string)$value)));sort($parts);return implode('|',$parts); }
function basic_quality_option_weights(string $dimCode): array { static $cache=[];if(isset($cache[$dimCode]))return $cache[$dimCode];if($dimCode==='')return $cache[$dimCode]=[];$st=db()->prepare("SELECT tier_label,tier_value FROM scoring_standard WHERE category='basic_quality' AND dim_code=? AND status='published'");$st->execute([$dimCode]);$weights=[];foreach($st->fetchAll() as $row)$weights[(string)$row['tier_label']]=max(0,(float)$row['tier_value']);return $cache[$dimCode]=$weights; }
function score_multi_answer(mixed $selected,mixed $answer,float $maxScore,array $weights=[]): float { $picked=array_values(array_filter(explode('|',normalize_answer($selected)),fn($value)=>$value!==''));$meta=json_decode((string)$answer,true);if(is_array($meta)&&isset($meta['correct'])&&is_array($meta['correct'])){$correct=array_values(array_filter(array_map('strval',$meta['correct']),fn($value)=>$value!==''));$weights=is_array($meta['weights']??null)?$meta['weights']:$weights;}else{$correct=array_values(array_filter(explode('|',normalize_answer($answer)),fn($value)=>$value!==''));}if(!$picked||!$correct||array_diff($picked,$correct))return 0;$totalWeight=0;$pickedWeight=0;foreach($correct as $value){$weight=array_key_exists($value,$weights)?$weights[$value]:1;$totalWeight+=$weight;if(in_array($value,$picked,true))$pickedWeight+=$weight;}if($totalWeight<=0)return 0;return round($maxScore*$pickedWeight/$totalWeight,2); }
function recalc_h5_result(int $answerId): void {
 $pdo=db();$st=$pdo->prepare("SELECT question_type,SUM(score) got,SUM(max_score) max_score,SUM(CASE WHEN score_status='manual_pending' THEN 1 ELSE 0 END) pending FROM answer_detail WHERE answer_id=? GROUP BY question_type");$st->execute([$answerId]);$g=[];$pending=0;foreach($st->fetchAll() as $r){$g[$r['question_type']]=(float)$r['max_score']>0?round((float)$r['got']/(float)$r['max_score']*25,1):0;$pending+=(int)$r['pending'];}$old=$pdo->prepare('SELECT eval_score FROM result WHERE answer_id=?');$old->execute([$answerId]);$eval=(float)$old->fetchColumn();$suzhi=$g['base']??0;$postq=$g['post']??0;$total=$pending?0:round($eval+$suzhi+$postq,1);$weights=json_encode(['basic_conditions'=>50,'basic_quality'=>25,'professional'=>25],JSON_UNESCAPED_UNICODE);$pdo->prepare('UPDATE result SET suzhi_score=?,postq_score=?,total_score=?,weight_snapshot=?,score_status=? WHERE answer_id=?')->execute([$suzhi,$postq,$total,$weights,$pending?'manual_pending':'completed',$answerId]);
}
